package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The pools on a sheet and their members. */
@Service
public class PoolService {

    /** The most a member's share can be, and what a balanced pool's shares total. */
    public static final BigDecimal FULL = new BigDecimal("100.00");

    /** A member of a pool as it stands: the person, their share, and whether they are retired. */
    public record Member(Person person, BigDecimal share) {

        /** What the share counts toward the pool's total: nothing once the person is retired, whatever the date. */
        public BigDecimal counted() {
            return person.isRetired() ? BigDecimal.ZERO.setScale(2) : share;
        }
    }

    /** A pool with its members, in the order they were added. */
    public record PoolWithMembers(Pool pool, List<Member> members) {

        /** The members' shares added up, a retired member's counting as 0.00. */
        public BigDecimal totalShare() {
            return members.stream().map(Member::counted).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        }

        /** Balanced when the shares total exactly 100.00. */
        public boolean balanced() {
            return totalShare().compareTo(FULL) == 0;
        }
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Audit audit;

    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            SheetService sheets, SheetRepository sheetStore, Audit audit) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
    }

    /** The sheet's pools, in the order they were added, each with its members. */
    @Transactional(readOnly = true)
    public List<PoolWithMembers> list(String sheetId) {
        List<Pool> list = pools.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PoolMember>> byPool = members.findByPoolIdInOrderByIdAsc(list.stream().map(Pool::getId).toList())
                .stream().collect(Collectors.groupingBy(PoolMember::getPoolId));
        return list.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()).stream()
                .filter(m -> byId.containsKey(m.getPersonId()))
                .map(m -> new Member(byId.get(m.getPersonId()), m.getShare())).toList())).toList();
    }

    /** Add a pool by its name, trimmed; refused when blank or already a pool on the sheet. */
    @Transactional
    public Pool add(String sheetId, String user, String name) {
        String key = name == null ? "" : name.strip();
        if (key.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A pool has a name");
        }
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        if (pools.existsBySheetIdAndName(sheetId, key)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet");
        }
        Pool saved;
        try {
            saved = pools.saveAndFlush(new Pool(sheetId, key));
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That pool is already on the sheet");
        }
        audit.recordChangeOnCommit(sheetId, user, "POOL_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName());
        return saved;
    }

    /** Add a person of the sheet to the pool with a share percent; refused when the person is already in it,
     *  or the share is not more than 0.00 and at most 100.00 with up to two decimals. */
    @Transactional
    public PoolWithMembers addMember(String sheetId, String user, long poolId, long personId, BigDecimal share) {
        if (share == null || share.signum() <= 0 || share.compareTo(FULL) > 0
                || share.stripTrailingZeros().scale() > 2) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A share is more than 0.00 and at most 100.00, with up to two decimals");
        }
        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        Pool pool = pools.findById(poolId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool on this sheet"));
        Person person = people.findById(personId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (members.existsByPoolIdAndPersonId(pool.getId(), personId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool");
        }
        try {
            members.saveAndFlush(new PoolMember(pool.getId(), personId, scaled));
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the pool");
        }
        audit.recordChangeOnCommit(sheetId, user, "POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user
                + " pool=" + pool.getName() + " name=" + person.getName() + " share=" + scaled.toPlainString());
        return list(sheetId).stream().filter(p -> p.pool().getId().equals(pool.getId())).findFirst().orElseThrow();
    }
}
package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The pools on a sheet. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/pools")
public class PoolController {

    /** A member as the pool's row shows it. */
    public record MemberView(long personId, String name, String share, boolean retired) {

        public static MemberView of(PoolService.Member m) {
            return new MemberView(m.person().getId(), m.person().getName(), m.share().toPlainString(),
                    m.person().isRetired());
        }
    }

    /** A pool as the screen shows it: its members, their total share and whether that is exactly 100.00. */
    public record PoolView(long id, String name, List<MemberView> members, String totalShare, boolean balanced) {

        public static PoolView of(PoolService.PoolWithMembers p) {
            return new PoolView(p.pool().getId(), p.pool().getName(), p.members().stream().map(MemberView::of).toList(),
                    p.totalShare().toPlainString(), p.balanced());
        }
    }

    /** A pool as the form submits it. */
    public record PoolForm(@NotNull @Size(max = 200) String name) {
    }

    /** A member as the pool's row submits it. */
    public record MemberForm(@NotNull Long personId, @NotNull BigDecimal share) {
    }

    private final PoolService pools;

    public PoolController(PoolService pools) {
        this.pools = pools;
    }

    @GetMapping
    public List<PoolView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        return pools.list(sheetId).stream().map(PoolView::of).toList();
    }

    @PostMapping
    public PoolView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PoolForm request) {
        return PoolView.of(new PoolService.PoolWithMembers(pools.add(sheetId, user, request.name()), List.of()));
    }

    @PostMapping("/{poolId}/members")
    public PoolView addMember(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long poolId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MemberForm request) {
        return PoolView.of(pools.addMember(sheetId, user, poolId, request.personId(), request.share()));
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

/** A share percent the pool's row accepts: up to two decimals (more than 0.00 and at most 100.00 is checked apart). */
export const SHARE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** A member of a pool: a person of the sheet with their share percent. */
export interface PoolMemberView {
  personId: number;
  name: string;
  share: string;
  /** Retired as soon as a retirement date is set: their share then counts as 0.00 toward the total. */
  retired: boolean;
}

/** A pool on the sheet: its members, their total share, and balanced when that is exactly 100.00. */
export interface PoolView {
  id: number;
  name: string;
  members: PoolMemberView[];
  totalShare: string;
  balanced: boolean;
}

// The pools on the active sheet, in the order they were added.
@Injectable({ providedIn: 'root' })
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly list = signal<PoolView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's pools from the store; null clears them. */
  load(sheetId: string | null): Observable<PoolView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<PoolView[]>(this.base(sheetId)).pipe(tap((list) => this.list.set(list)));
  }

  /** Add a pool; refused when the name is blank or already a pool on the sheet. */
  add(sheetId: string, name: string): Observable<PoolView> {
    return this.http.post<PoolView>(this.base(sheetId), { name }).pipe(
      tap((added) => this.list.update((list) => [...list, added])),
    );
  }

  /** Add a person to a pool with a share; refused when they are already in it or the share is out of range. */
  addMember(sheetId: string, poolId: number, personId: number, share: string): Observable<PoolView> {
    return this.http.post<PoolView>(`${this.base(sheetId)}/${poolId}/members`, { personId, share }).pipe(
      tap((saved) => this.list.update((list) => list.map((p) => (p.id === saved.id ? saved : p)))),
    );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/pools`;
  }
}

